        $previousSealToken = null;
        $visiblePointerMaps = [];
        $freeblockPublished = false;

        foreach ($checkpointRows as $index => $checkpointRow) {
            $pageNumber = (int) $checkpointRow['checkpoint_page'];
            $channel = (string) $checkpointRow['checkpoint_channel'];
            $ordinal = $index + 1;

