            $handoffToken = (string) $handoffRow['handoff_token'];
            $writeOffset = (int) $handoffRow['handoff_write_offset'];
            $channel = $isBarrier ? 'pointer-map-replay-barrier' : 'freeblock-consume-ready';
            $token = self::signature([
