            'action' => 'btree-vacuum-pointermap-freeblock-current-source-next190',
            'lease_summary' => $this->leaseSummary(),
            'lease_errors' => $this->leaseErrors(),
            'lease_rows' => $this->leaseRows,
            'base_plan' => $this->basePlan->toArray(),
        ];
