                'writer_admission_key' => self::signature([
                    (int) $row['page_number'],
                    $reuseChannel,
                    $receiptKind,
                    $admitted ? $writerOrdinal : 'not-admitted',
                    $readerVisible ? 'reader-visible' : 'reader-fenced',
                    $pointerMapSafe ? 'pointer-map-safe' : 'pointer-map-unsafe',
