                $firstLeaf = (int) $row['commit_ordinal'];
            }
            if ($row['commit_channel'] === 'overflow-freelist' && $firstOverflow === null) {
                $firstOverflow = (int) $row['commit_ordinal'];
            }
        }

        return $firstLeaf !== null && $firstOverflow !== null && $firstLeaf < $firstOverflow;
    }

